GUIDES_SEED = [{'id': 'guide_aadhaar', 'document_id': 'aadhaar', 'what_it_is': 'Aadhaar is a 12-digit unique identification number issued by the Unique Identification Authority of India (UIDAI) to residents. It serves as proof of identity and address across most government services.', 'documents_required': ['Proof of Identity (e.g., PAN Card, Passport, Voter ID)', 'Proof of Date of Birth (Birth Certificate, School Leaving Certificate)', 'Proof of Address (Utility bill, Bank Statement, Rental Agreement)'], 'procedure_steps': ['Visit the nearest Aadhaar Enrolment Centre (find one on the UIDAI website — uidai.gov.in)', 'Fill in the Aadhaar Enrolment/Correction Form at the centre', 'Submit original documents for verification (they are returned immediately)', 'Provide biometrics — fingerprints and iris scan', 'Collect the Enrolment ID / Acknowledgement slip', 'Aadhaar card is mailed to your address or can be downloaded online after generation (typically within 90 days)'], 'where_how_to_apply': 'Aadhaar Enrolment / Update Centre — locate via uidai.gov.in. Some post offices and bank branches also serve as enrolment centres.', 'precautions': ['Carry original documents — photocopies alone are not accepted at enrolment', 'Ensure name spelling matches exactly across all submitted documents', 'Retain the Enrolment ID slip carefully', 'Do not share your Aadhaar OTP or biometric details with anyone'], 'official_link': 'https://uidai.gov.in', 'verified': True}, {'id': 'guide_affidavit_stamp_paper', 'document_id': 'affidavit_stamp_paper', 'what_it_is': "An affidavit on stamp paper is a sworn statement made by the applicant, attested by a Notary Public or First Class Judicial Magistrate. For caste-related applications, it typically declares the applicant's caste, domicile, and other relevant facts. The denomination of stamp paper (e.g., Rs. 100, Rs. 200) varies by state and purpose.", 'documents_required': ['Aadhaar Card (for identity verification at the Notary office)', 'Draft of the affidavit text (usually provided by the office handling your application)'], 'procedure_steps': ['Obtain the prescribed affidavit format from the office where you are applying (e.g., Tehsil, Caste Scrutiny Committee)', 'Purchase a non-judicial stamp paper of the prescribed denomination from a licensed stamp vendor', 'Get the affidavit text typed on the stamp paper by a registered document writer or typist', 'Carry the stamp paper and your Aadhaar to a Notary Public or First Class Magistrate', 'Read the affidavit carefully and sign/thumb-print it in front of the Notary', 'The Notary affixes their seal and signs — the affidavit is now attested', 'Keep multiple photocopies of the attested affidavit'], 'where_how_to_apply': 'Licensed stamp vendors (near court premises or post offices), Notary Public offices (usually near district court), or First Class Judicial Magistrate offices. ', 'precautions': ['Verify the correct stamp paper denomination with the issuing office before purchase', 'Ensure the affidavit text matches the prescribed format exactly', 'Do not sign the affidavit before reaching the Notary — signature must be given in their presence', 'Check spelling of all names and dates carefully before signing'], 'official_link': 'https://gras.mahakosh.gov.in', 'verified': True}, {'id': 'guide_residence_proof', 'document_id': 'residence_proof', 'what_it_is': 'A residence proof (also called address proof) is any government-accepted document that shows your current residential address. Many government services accept a range of documents as address proof — a recent utility bill, Aadhaar, ration card, or bank passbook are common options.', 'documents_required': ['Aadhaar Card (which itself serves as address proof if address is current)', 'Any one of: recent electricity/water/gas bill (not older than 3 months), ration card, bank passbook first page, rent agreement'], 'procedure_steps': ['Check whether your Aadhaar address is current and accurate — if yes, Aadhaar itself may be accepted as address proof', 'If Aadhaar address is outdated, collect a recent utility bill (electricity, water, gas) in your name from your address', 'If you are a tenant, obtain a registered rent agreement or a landlord-issued letter with their ID proof', 'If none of these are available, obtain a domicile/residence certificate from your Tehsil office (requires Aadhaar and an application)'], 'where_how_to_apply': 'Most address proof documents are already in your possession (utility bills, ration card). A formal Domicile/Residence Certificate can be obtained from the Tehsil / Revenue office in your area.', 'precautions': ['Ensure the document shows your full current address clearly', 'Utility bills must typically be not older than 3 months — verify the requirement with the issuing office', 'If using a rent agreement, ensure it is registered (unregistered agreements may not be accepted everywhere)'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_caste_certificate', 'document_id': 'caste_certificate', 'what_it_is': 'A Caste Certificate is an official document issued by the Revenue Department certifying that the holder belongs to a particular Scheduled Caste (SC), Scheduled Tribe (ST), or Other Backward Class (OBC) as notified by the Central or State Government. It is essential for availing reservations and government welfare schemes.', 'documents_required': ['Aadhaar Card', 'Proof of Residence (Ration Card / Electricity Bill / Rent Agreement)', 'Affidavit on prescribed stamp paper declaring your caste', 'Passport-size photographs (quantity as prescribed)', 'Self-declaration form in prescribed format'], 'procedure_steps': ['Visit your nearest Tehsil office or Sub-Divisional Magistrate (SDM) office', 'Collect the Caste Certificate application form (or download from state portal if available)', 'Fill the form accurately with all personal and caste details', 'Attach self-attested photocopies of Aadhaar, residence proof, and affidavit', 'Submit the form at the designated counter and collect an acknowledgement receipt', 'An inquiry may be conducted by a revenue officer to verify your caste claim', 'Collect the Caste Certificate once issued (timeline varies by state — typically 15–30 working days; verify)'], 'where_how_to_apply': 'Tehsil Office / Sub-Divisional Magistrate (SDM) Office in your area. Some states offer online application through the state revenue portal — check your state government website.', 'precautions': ['Ensure caste name is spelled exactly as it appears in the Central/State Government notification list', 'Keep attested photocopies of all submitted documents', 'Retain the acknowledgement receipt until you receive the certificate', 'Do not approach touts or middlemen — apply directly at the government counter'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_school_leaving_certificate', 'document_id': 'school_leaving_certificate', 'what_it_is': "A School Leaving Certificate (SLC) or Transfer Certificate (TC) is issued by the last school attended, recording the student's name, date of birth, caste, and date of leaving. It is required for caste validity applications as it serves as an early record of caste entry.", 'documents_required': ['School admission register entry / original fee receipts', 'Aadhaar Card (for identity verification)'], 'procedure_steps': ['Write a formal application addressed to the Principal of your last attended school, requesting an SLC/TC', 'Mention your full name, admission number, year of study, and reason for requirement', 'Submit the application at the school office', 'Pay any nominal fee if prescribed by the school', 'Collect the SLC once signed and sealed by the Principal'], 'where_how_to_apply': 'The school office of the last school attended by the applicant. For very old records, approach the district / state Board of Education office.', 'precautions': ['Check that the caste entry in the SLC matches your current caste certificate exactly', 'If the school is closed or records are lost, approach the District Education Officer for assistance', 'Keep multiple certified copies of the SLC'], 'official_link': 'https://education.maharashtra.gov.in', 'verified': True}, {'id': 'guide_relative_validity_record', 'document_id': 'relative_validity_record', 'what_it_is': "A Relative's Caste Validity Record is a certified copy of a blood relative's (parent, sibling, uncle/aunt) Caste Validity Order issued by the Caste Scrutiny Committee. Submitting this can strengthen your own validity application by showing that a close relative's caste claim has already been verified.", 'documents_required': ['Caste Certificate of the relative', 'Relationship proof (birth certificate, school records showing family details)', "Copy of the relative's Caste Validity Order"], 'procedure_steps': ['Obtain the original Caste Validity Order of the qualifying blood relative', 'Apply for a certified true copy at the office of the Caste Scrutiny Committee that issued the original order', 'Submit the certified copy along with a relationship affidavit as part of your own validity application'], 'where_how_to_apply': 'Office of the Caste Scrutiny Committee (district/divisional level — verify the jurisdiction with local authorities).', 'precautions': ['Only orders from blood relatives qualify — in-laws or adoptive relatives may not be accepted', 'Verify the acceptable degrees of kinship with the Scrutiny Committee before applying', 'Relationship must be clearly documented'], 'official_link': 'https://bartievalidity.maharashtra.gov.in', 'verified': True}, {'id': 'guide_admission_letter', 'document_id': 'admission_letter', 'what_it_is': "An Admission Letter (or Offer Letter / Allotment Letter) is issued by an educational institution to a student confirming their admission. It typically contains the student's name, course, academic year, and institution details.", 'documents_required': ['Qualifying examination marksheet / result', 'Previous school/college documents'], 'procedure_steps': ["Apply for admission through the institution's prescribed process (centralised admission / direct application)", 'Once selected, the institution issues an Offer/Allotment letter', 'Accept the offer and complete the admission formalities', 'Collect the formal Admission Confirmation letter from the admission office'], 'where_how_to_apply': 'The admissions office of the educational institution where you have been admitted.', 'precautions': ['Ensure the letter is on institution letterhead with proper stamp/seal', 'Verify that your name, course, and year are correctly stated', 'Keep the original safely; carry photocopies for submission'], 'official_link': 'https://cetcell.mahacet.org', 'verified': True}, {'id': 'guide_income_proof', 'document_id': 'income_proof', 'what_it_is': 'An Income Proof certifies the annual income of the applicant and/or their family. Acceptable forms include a salary certificate from the employer, Form 16 (for salaried employees), an income certificate from the Tehsil office (for non-salaried individuals), or recent payslips.', 'documents_required': ['Aadhaar Card', 'Proof of Residence', 'Employment details / salary records (if salaried)', 'Self-declaration of income (if self-employed or agricultural worker)'], 'procedure_steps': ['If salaried: obtain a salary certificate or Form 16 from your employer, or download recent payslips', 'If self-employed / business owner: obtain a CA-certified income statement or a self-declaration with supporting documents', 'If agricultural worker or informal sector: apply for an Income Certificate from the Tehsil office by submitting Aadhaar, residence proof, and a self-declaration', 'The Tehsil office conducts an inquiry and issues an Income Certificate (timeline varies — typically 15–30 days)'], 'where_how_to_apply': 'For an official Income Certificate: Tehsil / SDM Office. For employer-issued documents: your HR / employer.', 'precautions': ["Ensure income stated covers the full financial year and all family members' income", 'Do not under-declare income — this is a punishable offence', 'Check the date of validity as some schemes require a certificate not older than 6 or 12 months'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_self_declaration_form', 'document_id': 'self_declaration_form', 'what_it_is': 'A Self-Declaration Form is a form prescribed by the issuing authority in which the applicant declares relevant facts (identity, caste, income, domicile, etc.) under their own signature. It is not notarised but is legally binding. The prescribed format varies by service.', 'documents_required': ['Aadhaar Card (for reference when filling the form)'], 'procedure_steps': ['Obtain the prescribed Self-Declaration Form from the issuing office OR download it from the official portal', 'Fill in all fields accurately and legibly using blue/black ink', 'Sign and date the form — DO NOT sign in advance; sign only when submitting or in front of the officer if required', 'Submit as part of your main application'], 'where_how_to_apply': 'The self-declaration form is available at the counter of the issuing office (Tehsil, Caste Scrutiny Committee, etc.) or sometimes downloadable from the state government portal.', 'precautions': ['Use only the prescribed format — unofficial formats may be rejected', 'Ensure all declarations are truthful; false declarations can lead to cancellation and legal action', 'Take a photocopy of the filled form before submission'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_photograph', 'document_id': 'photograph', 'what_it_is': "A passport-size photograph is a standard-sized (typically 3.5 cm × 4.5 cm) colour photograph taken against a plain white or light background, showing the applicant's face clearly without glasses (unless medically necessary). Most government applications require 2–6 such photographs.", 'documents_required': [], 'procedure_steps': ['Visit a registered photo studio', 'Request passport-size photographs (specify quantity — typically 6 is a safe number to carry)', 'Photographs should be recent (not older than 6 months typically — verify the requirement)'], 'where_how_to_apply': 'Any registered / local photo studio. Some banks and post offices also provide this service.', 'precautions': ['Photographs should have a plain white or light background', 'Face should be clearly visible, no sunglasses or caps', 'Take extra copies — they are inexpensive and often required in multiples'], 'official_link': 'https://uidai.gov.in', 'verified': True}, {'id': 'guide_pre_1950_caste_proof', 'document_id': 'pre_1950_caste_proof', 'what_it_is': "A pre-1950 or pre-1967 ancestral document proves that the applicant's forefathers resided in the state and belonged to the declared caste before the statutory cutoff dates specified in state reservation acts.", 'documents_required': ['Aadhaar of applicant', 'Genealogical relationship chart', 'Old school leaving certificate or birth/death registry extract of father/grandfather'], 'procedure_steps': ['Identify which primary or secondary school your father, grandfather, or great-grandfather attended', 'Apply to the Headmaster of the school or Zilla Parishad education officer for a certified true copy (duplicate extract) of the General Register (GR)', 'Alternatively, apply at the Tehsil / Municipal Archives for a certified extract of the Birth and Death Register prior to 1950/1967', 'Ensure the caste column clearly mentions the recognized community name exactly matching the constitutional order', 'Get the extract counter-attested by the Block Education Officer (BEO) or Executive Magistrate'], 'where_how_to_apply': 'Primary school where ancestor studied, Municipal/Gram Panchayat birth archives, or District Collectorate record room.', 'precautions': ['Check that the caste name is not abbreviated and has no alterations or overwriting', 'Ensure the document is certified with official stamp and signature', 'Keep original and laminated photocopies safe'], 'official_link': 'https://bartievalidity.maharashtra.gov.in', 'verified': True}, {'id': 'guide_delhi_3yr_residence_proof', 'document_id': 'delhi_3yr_residence_proof', 'what_it_is': 'Proof demonstrating continuous physical residence within the National Capital Territory of Delhi for a consecutive period of at least 3 years.', 'documents_required': ['Aadhaar with Delhi address', 'Electricity bills for the last 3 years', 'Registered rent agreement or Voter ID'], 'procedure_steps': ["Gather consecutive electricity or water bills in your or parent's name covering the last 3 years", 'If living in rented premises, gather registered rent agreements or landlord verification letter with electricity meters', 'Download previous 3 years utility bills from BSES/TPDDL consumer portal', 'Compile into chronological order ready for e-District upload'], 'where_how_to_apply': 'BSES Rajdhani/Yamuna or Tata Power DDL portal, or respective discom customer care office.', 'precautions': ['Ensure address spelling matches your Aadhaar and identity proof exactly', 'Do not provide bills with gaps exceeding 6 months without explanation'], 'official_link': 'https://edistrict.delhigovt.nic.in', 'verified': True}, {'id': 'guide_parivar_register_nakal', 'document_id': 'parivar_register_nakal', 'what_it_is': 'Parivar Register Nakal (Family Register Extract) is a certified copy of the family record maintained by the Panchayati Raj or Urban Development authority.', 'documents_required': ['Aadhaar of head of household', 'Application form', 'Ration card'], 'procedure_steps': ['Visit the Gram Panchayat Secretary (Gram Vikas Adhikari) in rural areas, or Executive Officer of Nagar Palika / Nigam in urban areas', 'Submit an application requesting Parivar Register Nakal copy', 'Secretary verifies the Kutumb Register entry and prepares the extract with seal', 'In UP, you can also apply online through the eSathi UP portal (esathi.up.gov.in)', 'Pay the nominal fee (typically Rs. 5 to Rs. 20) and collect receipt'], 'where_how_to_apply': 'Gram Panchayat Office (Village Secretary) or Nagar Palika / Nagar Nigam office, or eSathi portal.', 'precautions': ['Ensure all members of your nuclear and joint family are listed with correct age and relationship', 'Check that the head of family name matches your records'], 'official_link': 'https://edistrict.up.gov.in', 'verified': True}, {'id': 'guide_pedhinama', 'document_id': 'pedhinama', 'what_it_is': 'A Pedhinama is a certified family genealogy chart showing direct ancestral lineage from the forefather down to the applicant, essential in Gujarat and western states.', 'documents_required': ['Aadhaar of all family members', 'Death certificates of deceased ancestors', 'Affidavit on non-judicial stamp paper', 'Panchkyas (statement of 2 local village panchas/witnesses)'], 'procedure_steps': ['Draw the genealogical tree starting from great-grandfather down to all living heirs', 'Prepare a sworn affidavit on Rs. 100/300 stamp paper stating the pedigree tree', 'Take statements of two respected village elders / Panchas before the Talati', 'Talati cum Mantri conducts verification against village records (Form 7/12 or 8A)', 'Talati prepares the Rojkam and signs the Pedhinama', 'Counter-signed or endorsed by the Mamlatdar / Executive Magistrate'], 'where_how_to_apply': 'Office of the Talati cum Mantri (e-Gram Panchayat) or Mamlatdar Office.', 'precautions': ['Include all legal heirs including married daughters where required by state revenue code', 'Do not omit any deceased ancestor'], 'official_link': 'https://digitalgujarat.gov.in', 'verified': True}, {'id': 'guide_nadakacheri_rd_number', 'document_id': 'nadakacheri_rd_number', 'what_it_is': 'A 15-digit RD acknowledgment number issued by the Karnataka Revenue Department when applying for certificates through Atalji Janasnehi Kendra.', 'documents_required': ['Aadhaar Card', 'Ration card', 'Mobile number linked with Aadhaar'], 'procedure_steps': ['Visit the Nadakacheri portal (nadakacheri.karnataka.gov.in) or Seva Sindhu', 'Click Online Application and select the revenue service', 'Enter your details and upload supporting documents', 'On submission, an acknowledgment slip containing a unique 15-digit RD barcode number (e.g., RD0038...) is generated', 'Note down or print this RD number for tracking and verification'], 'where_how_to_apply': 'nadakacheri.karnataka.gov.in or any Atalji Janasnehi Kendra (AJSK) counter across Karnataka.', 'precautions': ['Keep the acknowledgment PDF saved safely with the barcode visible', 'Check application status online using this RD number'], 'official_link': 'https://nadakacheri.karnataka.gov.in', 'verified': True}, {'id': 'guide_talati_verification_report', 'document_id': 'talati_verification_report', 'what_it_is': 'An official spot inquiry report issued by the Village Revenue Officer (Talati/Patwari/Lekhpal) documenting actual income, residence, or family landholdings.', 'documents_required': ['Aadhaar Card', 'Electricity or land revenue tax receipt', 'Self-declaration of annual family income'], 'procedure_steps': ['File an application at the Tehsil office or online portal for income/caste verification', 'The application is automatically marked to the local Talati / Lekhpal of your circle', 'Talati conducts a local inquiry with neighbors or examines revenue records', 'Talati writes the Panchnama / spot inquiry report and enters annual income figure', 'Report is uploaded to the portal or forwarded to the Tehsildar'], 'where_how_to_apply': 'Local Talati/Patwari office or Village Panchayat / Tehsil office.', 'precautions': ['Present genuine income documents (salary slips, agricultural J-Form, or returns)', 'Ensure phone number is active for the officer to contact you for the site visit'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_domicile_certificate', 'document_id': 'domicile_certificate', 'what_it_is': 'A Domicile Certificate certifies that an individual has lived in a specific state for the statutory period (typically 10 to 15 years) or is a bona fide resident.', 'documents_required': ['Aadhaar Card', 'Birth certificate or School LC showing birthplace', 'Continuous residence proof for 10-15 years (ration card, utility bills, tax receipts)', 'Passport photos'], 'procedure_steps': ['Log in to your state citizen services portal (e.g., Aaple Sarkar, e-District, Seva Sindhu)', "Select 'Domicile Certificate' or 'Resident Certificate' under Revenue Department", 'Upload birth certificate, continuous residence proof, and affidavit', 'Pay application processing fee and submit', 'Tahsildar / SDM issues the digital certificate upon revenue verification (usually within 15-21 days)'], 'where_how_to_apply': 'State citizen services portal or Tehsil / SDM Office / CSC Kendra.', 'precautions': ['Proof of residence must cover the full prescribed duration without major unexplained gaps', 'A person can legally hold domicile of only one state at a time'], 'official_link': 'https://aaplesarkar.mahaonline.gov.in', 'verified': True}, {'id': 'guide_kutumba_sats_id', 'document_id': 'kutumba_sats_id', 'what_it_is': "Kutumba is Karnataka's Entitlement Management System assigning a single unified Family ID, while SATS is the Student Achievement Tracking System ID used for scholarships.", 'documents_required': ['Aadhaar of student and family members', 'Ration card', 'School enrollment number'], 'procedure_steps': ['Check existing Kutumba ID at kutumba.karnataka.gov.in using your Ration Card or Aadhaar', 'If not registered, update family details through the Grama One or Bangalore One center', 'Obtain your 9-digit SATS Student ID from your school or college administrative office', 'Both IDs automatically pre-populate your family income and caste data on the State Scholarship Portal (SSP)'], 'where_how_to_apply': 'kutumba.karnataka.gov.in, ssp.postmatric.karnataka.gov.in, or nearest Grama One center.', 'precautions': ['Ensure Aadhaar name matches school enrollment records exactly', 'Confirm your bank account is active and seeded with Aadhaar on NPCI mapper'], 'official_link': 'https://kutumba.karnataka.gov.in', 'verified': True}]

